from pathlib import Path
from urllib.parse import quote
root=Path(__file__).resolve().parents[1]/'dist'
favicon='data:image/svg+xml,'+quote('<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 64 64"><rect width="64" height="64" rx="15" fill="#2258b5"/><text x="32" y="43" text-anchor="middle" font-family="Arial" font-size="34" font-weight="bold" fill="white">N</text></svg>')
def page(route,title,desc,content):
    depth=len(route.strip('/').split('/')) if route else 0
    base='../'*depth or './'
    content=content.replace('@/',base)
    out=root/route;out.mkdir(parents=True,exist_ok=True)
    (out/'index.html').write_text(f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>{title}</title><meta name="description" content="{desc}"><link rel="icon" href="{favicon}"><link rel="stylesheet" href="{base}assets/style.css"></head><body><a class="skip" href="#main">Skip to content</a><header><a class="brand" href="{base}">Netanel<span>Vision</span></a><nav aria-label="Main"><a href="{base}">Apps</a><a href="mailto:netanelvision@gmail.com">Contact</a></nav></header>{content}<footer><span>© 2026 NetanelVision</span><div><a href="{base}anywarranty/privacy/">Any.Warranty Privacy</a><a href="{base}anywarranty/terms/">Any.Warranty Terms</a><a href="mailto:netanelvision@gmail.com">Support</a></div></footer></body></html>''')
page('', 'NetanelVision — Apps for everyday life','Explore Any.Warranty and Expense Manager by NetanelVision.', '''<main id="main"><section class="intro"><div class="eyebrow">Independent apps. Everyday usefulness.</div><h1>A little more order.<br>A lot less effort.</h1><p class="lead">Thoughtful apps from NetanelVision, built to make the everyday easier.</p></section><article class="app-card"><div class="card-copy"><div class="eyebrow">Our apps / 01</div><h2>Any.Warranty</h2><p class="lead">Your receipts and warranties.<br>Right where you need them.</p><p>Keep purchase details, documents, and warranty dates together on your iPhone.</p><a class="button" href="@/anywarranty/">Explore Any.Warranty</a></div><div class="art"><img src="@/assets/anywarranty.png" alt="Any.Warranty app icon" width="1024" height="1024"></div></article><article class="app-card expense-card"><div class="card-copy"><div class="eyebrow">Our apps / 02</div><h2>Expense Manager</h2><p class="lead" lang="he" dir="rtl">כלכלת הבית — הכסף שלכם, בתמונה אחת.</p><p>Track income, expenses and savings. Keep receipts close, explore your spending and plan your household budget.</p><a class="button" href="@/expense-manager/">Explore Expense Manager · עברית</a></div><div class="art expense-art"><img src="@/assets/expense-manager/icon.png" alt="Expense Manager app icon" width="1024" height="1024"></div></article></main>''')
page('anywarranty','Any.Warranty — NetanelVision','Keep receipts, purchase details, and warranty dates together with Any.Warranty for iPhone.', '''<main id="main"><section class="intro"><a class="back" href="@/">All apps</a><h1>Keep the receipt.<br>Lose the worry.</h1><p class="lead">Any.Warranty keeps the details of the things you own together, from the day you buy them to the day you need them.</p></section><section class="app-card"><div class="card-copy"><div class="eyebrow">Any.Warranty / iPhone</div><h2>A home for your<br>purchase details.</h2><p>Save receipt photos, serial numbers, notes, and warranty dates. Organize your items and find the information you need without searching through paperwork.</p><a class="button" href="mailto:netanelvision@gmail.com?subject=Any.Warranty%20support">Contact support</a></div><div class="art"><img src="@/assets/anywarranty.png" alt="Any.Warranty app icon" width="1024" height="1024"></div></section><section class="features" aria-label="Features"><div><span class="feature-number">01 / ORGANIZE</span><h2>Everything together</h2><p>Keep purchase details and receipt images with each item. Categories help you find your way back.</p></div><div><span class="feature-number">02 / REMEMBER</span><h2>Know your dates</h2><p>Track warranty expiration dates and set reminders for the items that matter.</p></div><div><span class="feature-number">03 / KEEP A COPY</span><h2>Your choice of backup</h2><p>Optional Google Drive and Dropbox backup and restore. Features depend on your installed app version.</p></div></section><div class="note"><h2>Your records. Your control.</h2><p>Records are stored on your device. Connect a cloud account when you want to use cloud backup. Google Drive backup uses the app’s private data folder.</p><a href="@/anywarranty/privacy/">Read the privacy policy</a> · <a href="@/anywarranty/terms/">Terms of use</a></div></main>''')
page('anywarranty/privacy','Any.Warranty Privacy Policy — NetanelVision','How Any.Warranty handles your records, photos, Google Drive and Dropbox backups, and support information.', '''<main id="main" class="legal"><section class="intro"><a class="back" href="@/anywarranty/">Any.Warranty</a><h1>Privacy policy</h1><p class="meta">Effective September 22, 2026</p><p>This policy describes how NetanelVision handles information in Any.Warranty and on this website. Contact: <a href="mailto:netanelvision@gmail.com">netanelvision@gmail.com</a>.</p></section><h2>Information you put in the app</h2><p>Any.Warranty stores the records you create, including item names, purchase details, serial numbers, categories, notes, warranty dates, reminders, and receipt or document images. These records are kept in the app’s local storage so you can organize and view your warranties.</p><h2>Device permissions</h2><p>Camera and photo permissions let you scan or attach documents. Notification permission lets the app show reminders. You can change these permissions in iOS Settings. Features that need a permission may be unavailable when it is disabled.</p><h2>Optional cloud backup</h2><p>If you connect Google Drive or Dropbox, the app can upload a copy of its database, including the records and images stored in it, to your selected cloud account and download it when you request a restore. A restore replaces the current app database. Depending on the app version and your settings, iCloud or your device’s backup service may also hold copies of app data.</p><h2>Google account and Google Drive data</h2><p>Google Sign-In provides account information, including your email address, to identify the connected backup account. Authentication credentials allow the app to access that account without asking for your Google password. Any.Warranty uses the Google Drive app-data permission to create, find, update, and download its own backup in a private application folder. This permission does not grant access to your ordinary Drive documents.</p><p>Google data is used to provide the sign-in, backup, and restore features you choose. It is not sold, used for advertising, or used to train AI models. Any.Warranty’s use and transfer of information received from Google APIs follows the <a href="https://developers.google.com/terms/api-services-user-data-policy">Google API Services User Data Policy</a>, including its Limited Use requirements.</p><h2>Sharing and service providers</h2><p>Cloud backups are sent to the provider you connect. Google, Dropbox, and Apple process information under their own policies. NetanelVision does not receive your cloud password. If you contact support, we receive your email address, message, and any attachments you send; we use them to respond and resolve your request. Please avoid sending sensitive receipt details unless needed for support.</p><h2>Website and service requests</h2><p>This website does not include advertising, analytics scripts, or tracking cookies. GitHub Pages hosts the website and may process IP addresses and technical request logs to operate and secure its service. App update-information requests may include the app version, language, and technical connection information. See <a href="https://docs.github.com/en/site-policy/privacy-policies/github-general-privacy-statement">GitHub’s privacy statement</a>.</p><h2>Storage, retention, and deletion</h2><p>Local records remain until you delete them or remove the app’s data. Cloud backups are separate copies and can remain after local records are deleted or the app is uninstalled. Manage or delete those backups through the relevant provider; for Google Drive, use its app-management settings to manage hidden app data. Revoking access or signing out stops future authorized access but does not itself delete existing backups.</p><p>You can revoke Google access in your Google Account’s third-party connections settings and manage Dropbox access in your Dropbox account. Support correspondence is retained as needed to handle the request and related follow-up. Email us to request access, correction, or deletion of information held by NetanelVision. We cannot directly delete records stored only on your device or in your personal cloud account.</p><h2>Protecting your information</h2><p>Access to your device and cloud account helps protect your records. Use a device passcode and protect your cloud credentials. No storage or transmission method can guarantee absolute security.</p><h2>Children and policy changes</h2><p>Any.Warranty is intended for general use and is not directed at children under 13. If you believe a child has sent us personal information, contact us. We may update this policy when the app or our practices change; the effective date above identifies the latest revision.</p><h2>Questions?</h2><p>Email <a href="mailto:netanelvision@gmail.com">netanelvision@gmail.com</a> for privacy questions or requests.</p></main>''')
page('anywarranty/terms','Any.Warranty Terms of Use — NetanelVision','Terms for using Any.Warranty and its optional backup services.', '''<main id="main" class="legal"><section class="intro"><a class="back" href="@/anywarranty/">Any.Warranty</a><h1>Terms of use</h1><p class="meta">Effective September 22, 2026</p><p>These terms apply to Any.Warranty, provided by NetanelVision. By using the app, you agree to these terms.</p></section><h2>Using the app</h2><p>Any.Warranty helps you organize purchase and warranty information. You are responsible for the records you add and for using the app lawfully. Store only information you have permission to use.</p><h2>Warranty information and reminders</h2><p>The app does not issue, extend, or guarantee a product warranty. Verify coverage and deadlines with the seller or manufacturer. Reminder delivery depends on your device and notification settings; keep independent records of important deadlines.</p><h2>Backups and third-party services</h2><p>Cloud services require your own account and are subject to the provider’s terms, availability, permissions, and storage limits. Keep an independent copy of important documents. Restoring a backup replaces local app records, and uploading a new backup may replace a previous copy.</p><h2>Availability</h2><p>Features may change or be unavailable temporarily. To the extent permitted by applicable law, the app is provided as available without guarantees of uninterrupted operation or error-free data recovery. These terms do not limit rights or remedies that cannot be excluded under applicable consumer law.</p><h2>Privacy and contact</h2><p>Read our <a href="@/anywarranty/privacy/">privacy policy</a> for details about information handling. Questions about the app or these terms can be sent to <a href="mailto:netanelvision@gmail.com">netanelvision@gmail.com</a>.</p></main>''')
page('404','Page not found — NetanelVision','This page could not be found.','<main id="main"><section class="intro"><div class="eyebrow">404</div><h1>Nothing here yet.</h1><p>Find your app on the NetanelVision homepage.</p><a class="button" href="@/">Explore our apps</a></section></main>')
