(root/'404.html').write_text((root/'404/index.html').read_text().replace('../','/appswebsite/'))
(root/'404/index.html').unlink();(root/'404').rmdir()
(root/'.nojekyll').touch()

page("expense-manager", "Expense Manager — כלכלת הבית | NetanelVision", "ניהול תקציב, הכנסות, הוצאות וחסכונות. קבלות, מסמכי PDF, גרפים, תזכורות והמרת מטבע בממשק בעברית.", '<main id="main"><section class="intro" lang="he" dir="rtl"><a class="back" href="@/">כל האפליקציות</a><div class="eyebrow">Expense Manager / כלכלת הבית</div><h1>יותר סדר בכסף.<br>יותר בהירות ביום־יום.</h1><p class="lead">התקציב, ההוצאות, הקבלות והחסכונות שלכם — במקום אחד. כלי מפורט לניהול כלכלת הבית, עם ממשק בעברית ותמונה ברורה של הנתונים שלכם.</p><a class="button" href="mailto:netanelvision@gmail.com?subject=Expense%20Manager">יצירת קשר ותמיכה</a></section><section class="features expense-features" lang="he" dir="rtl" aria-label="יכולות האפליקציה"><article><span class="feature-number">01</span><h2>תקציב שרואים ומבינים</h2><p>מעקב אחר הכנסות, הוצאות ומאזן לפי יום, שבוע, חודש, רבעון ושנה. גרפים ופילוח לפי קטגוריות עוזרים להבין לאן הכסף הולך.</p></article><article><span class="feature-number">02</span><h2>תקרות הוצאה לפי קטגוריה</h2><p>הגדירו תקציב חודשי לקטגוריות, ראו כמה נוצל וכמה נשאר והתאימו את תחילת חודש התקציב לצרכים שלכם.</p></article><article><span class="feature-number">03</span><h2>מקום גם לחסכונות</h2><p>תעדו ניירות ערך, קופות גמל, מט״ח וכל סוג חיסכון שתבחרו. עדכנו שווי בתאריכים שונים, בחרו חסכונות להשוואה והציגו את השינוי בסכום, באחוזים ובגרף.</p></article><article><span class="feature-number">04</span><h2>קבלות ומסמכים מסודרים</h2><p>צלמו קבלה או בחרו תמונה, צרפו אותה לעסקה ושמרו כותרת וכתובת. זיהוי פרטים מתמונות מסייע במילוי הנתונים לבדיקה שלכם. מסמכי PDF מרובי עמודים זמינים לשמירה, צפייה ושיתוף, ללא זיהוי טקסט.</p></article><article><span class="feature-number">05</span><h2>גם הפעולות הקבועות מטופלות</h2><p>נהלו עסקאות חוזרות מדי יום, שבוע, חודש או שנה. הגדירו תזכורות יומיות, שבועיות או חודשיות כדי לשמור על שגרת רישום.</p></article><article><span class="feature-number">06</span><h2>חיפוש, דוחות ומטבעות</h2><p>חפשו עסקאות לפי טקסט וטווח תאריכים, צפו בסיכומים ובדוחות ונהלו קובצי תקציב נפרדים עם מטבע לכל תקציב. המרת מטבע מסייעת להזין הוצאות במטבע התקציב.</p></article><article><span class="feature-number">07</span><h2>גיבוי והגנה</h2><p>אפשרויות גיבוי ושחזור ב־iCloud וב־Dropbox, לצד גיבוי באימייל. בחרו נעילה באמצעות קוד או זיהוי פנים / טביעת אצבע, בהתאם למכשיר.</p></article><article><span class="feature-number">08</span><h2>מרגישה בבית בעברית</h2><p>ממשק בעברית ומימין לשמאל, תמיכה בשפות נוספות, מצב בהיר וכהה והתאמה של צבעים וגודל טקסט.</p></article></section><section lang="he" dir="rtl"><h2>מבט לתוך האפליקציה</h2><p class="lead">מהתקציב היומי ועד התמונה הרחבה של החסכונות.</p><div class="screenshots"><a href="@/assets/expense-manager/screen-1.jpg"><img loading="lazy" src="@/assets/expense-manager/screen-1.jpg" width="640" height="1385" alt="התקציב בתמונה אחת"></a><a href="@/assets/expense-manager/screen-2.jpg"><img loading="lazy" src="@/assets/expense-manager/screen-2.jpg" width="640" height="1385" alt="תקרות הוצאה"></a><a href="@/assets/expense-manager/screen-3.jpg"><img loading="lazy" src="@/assets/expense-manager/screen-3.jpg" width="640" height="1385" alt="מעקב אחר חסכונות"></a><a href="@/assets/expense-manager/screen-4.jpg"><img loading="lazy" src="@/assets/expense-manager/screen-4.jpg" width="640" height="1385" alt="הוספת עסקאות"></a><a href="@/assets/expense-manager/screen-5.jpg"><img loading="lazy" src="@/assets/expense-manager/screen-5.jpg" width="640" height="1385" alt="חיפוש מתקדם"></a><a href="@/assets/expense-manager/screen-7.jpg"><img loading="lazy" src="@/assets/expense-manager/screen-7.jpg" width="640" height="1385" alt="המרת מטבע"></a></div></section><aside class="note" lang="he" dir="rtl"><h2>הנתונים שלכם, בקצב שלכם</h2><p>הנתונים נשמרים במכשיר, עם אפשרויות גיבוי לבחירתכם. שינוי בשווי החסכונות עשוי לכלול הפקדות ומשיכות ואינו חישוב תשואת השקעה. המרת מטבע ושירותי ענן דורשים חיבור לרשת; תזכורות דורשות הרשאת התראות. זמינות התכונות תלויה בגרסה המותקנת.</p></aside></main>')
